package com.bank.recon;

import java.util.logging.Logger;

public class ReconGridSolver {

    private static final Logger log = Logger.getLogger(ReconGridSolver.class.getName());

    public boolean solve(char[][] board) {
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++)
                if (board[r][c] == '.') {
                    for (char d = '1'; d <= '9'; d++) {
                        if (isValid(board, r, c, d)) {
                            board[r][c] = d;                 // place candidate
                            if (solve(board)) return true;   // recurse
                            board[r][c] = '.';               // undo (backtrack)
                        }
                    }
                    return false;                            // no digit fits ⇒ backtrack
                }
        log.info("Reconciliation grid solved completely");
        return true;                                         // no empty cell ⇒ done
    }

    private boolean isValid(char[][] b, int r, int c, char d) {
        int br = (r / 3) * 3, bc = (c / 3) * 3;
        for (int i = 0; i < 9; i++) {
            if (b[r][i] == d || b[i][c] == d) return false;  // row & column
            if (b[br + i / 3][bc + i % 3] == d) return false; // 3×3 box
        }
        return true;
    }
}
