package com.bank.recon;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class SudokuDemo {

    private static final Logger log = Logger.getLogger(SudokuDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Reconciliation Grid Solver (Sudoku)");
        char[][] board = {
            {'5','3','.','.','7','.','.','.','.'},
            {'6','.','.','1','9','5','.','.','.'},
            {'.','9','8','.','.','.','.','6','.'},
            {'8','.','.','.','6','.','.','.','3'},
            {'4','.','.','8','.','3','.','.','1'},
            {'7','.','.','.','2','.','.','.','6'},
            {'.','6','.','.','.','.','2','8','.'},
            {'.','.','.','4','1','9','.','.','5'},
            {'.','.','.','.','8','.','.','7','9'}
        };
        ReconGridSolver solver = new ReconGridSolver();
        boolean solved = solver.solve(board);
        log.info("Solved = " + solved + "; cell[0][2]=" + board[0][2]);
    }
}
